// Turns each "Ready" row into a finished page (binary) or an error for that row.
// Generated by n8n/build-sheet-workflow.js from templates/; edit those, not this.
const TEMPLATE = "<!doctype html>\n<html lang=\"%%lang%%\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>%%title%%</title>\n<meta name=\"description\" content=\"%%description%%\">\n<link rel=\"canonical\" href=\"%%canonical_url%%\">\n<meta name=\"robots\" content=\"index, follow, max-snippet:-1, max-image-preview:large\">\n<meta name=\"author\" content=\"%%author%%\">\n\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:site_name\" content=\"%%site_name%%\">\n<meta property=\"og:title\" content=\"%%title%%\">\n<meta property=\"og:description\" content=\"%%description%%\">\n<meta property=\"og:url\" content=\"%%canonical_url%%\">\n<meta property=\"article:published_time\" content=\"%%date_published%%\">\n<meta property=\"article:modified_time\" content=\"%%date_modified%%\">\n%%image_meta%%\n<meta name=\"twitter:card\" content=\"%%twitter_card%%\">\n\n<script type=\"application/ld+json\">\n%%json_ld%%\n</script>\n\n<style>\n  :root { --bg: #ffffff; --fg: #1d232b; --muted: #5d6673; --line: #dde2e8; --accent: #0b5cad; --soft: #f3f6f9; }\n  @media (prefers-color-scheme: dark) {\n    :root { --bg: #12161c; --fg: #e4e8ed; --muted: #9aa4b1; --line: #2c3540; --accent: #7db4ef; --soft: #1a2029; color-scheme: dark; }\n  }\n  * { box-sizing: border-box; }\n  body { margin: 0; background: var(--bg); color: var(--fg);\n    font: 18px/1.65 -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif; }\n  .wrap { max-width: 42rem; margin: 0 auto; padding: 0 16px; }\n  .site { padding-block: 20px; font-size: 15px; }\n  .site a { color: var(--muted); text-decoration: none; }\n  .site a:hover { color: var(--accent); }\n  h1 { font-size: 2.1rem; line-height: 1.2; margin: 1.5rem 0 0.5rem; text-wrap: balance; }\n  h2 { font-size: 1.4rem; line-height: 1.3; margin: 2.2rem 0 0.6rem; text-wrap: balance; }\n  h3 { font-size: 1.1rem; line-height: 1.35; margin: 1.6rem 0 0.4rem; }\n  p { margin: 0 0 1rem; }\n  a { color: var(--accent); }\n  .meta { color: var(--muted); font-size: 15px; margin-bottom: 1.5rem; }\n  .lead { font-size: 1.15rem; }\n  .takeaways { background: var(--soft); border: 1px solid var(--line); border-radius: 8px; padding: 4px 20px 8px; margin: 2rem 0; }\n  .takeaways h2 { font-size: 1.05rem; margin-top: 1rem; }\n  .takeaways ul { margin: 0 0 0.5rem; padding-left: 1.2rem; }\n  .faq { border-top: 1px solid var(--line); margin-top: 2.5rem; }\n  footer.site { border-top: 1px solid var(--line); margin-top: 3rem; }\n</style>\n</head>\n<body>\n<header class=\"site wrap\"><a href=\"/\">%%site_name%%</a></header>\n\n<main class=\"wrap\">\n<article>\n  <header>\n    <h1>%%title%%</h1>\n    <p class=\"meta\">By %%author%% · <time datetime=\"%%date_published%%\">%%date_published_display%%</time>%%updated_note%%</p>\n    %%intro_html%%\n  </header>\n\n  %%takeaways_html%%\n\n  %%sections_html%%\n\n  %%faq_html%%\n</article>\n</main>\n\n<footer class=\"site wrap\"><a href=\"/\">← All posts</a></footer>\n</body>\n</html>\n";
const SETTINGS = {
  "bucket": "n8n-practice-site-748348796384",
  "distributionId": "ESU04REFQ1XCN",
  "site": {
    "url": "https://dpg9rn8ztrdt6.cloudfront.net",
    "name": "Practice site",
